		{ id = "greatmother-hawkwind", name = "Grã-mãe Hawkwind", note = "sua mãe" },
		{ id = "grull-hawkwind", name = "Grull Hawkwind", note = "seu filho" },
		{ id = "seer-graytongue", name = "Vidente Graytongue", note = "põe os jovens à prova a seu pedido" },
		{ id = "baine-bloodhoof", name = "Baine Bloodhoof", note = "recebe os que passam" },
	},
})

Translate("ptBR", "grull-hawkwind", {
	title = "Grull Hawkwind",
	subtitle = "Caçador da Chapada Nuvem Vermelha",
	found = "Aldeia Narache, na Chapada Nuvem Vermelha",
	hint = [=[Encontre o filho do chefe, que põe à prova os jovens caçadores de Narache.]=],
	allegiance = "Tauren · Aldeia Narache",
	aliases = { "Grull" },
	sections = {
		{
			title = "Resumo",
			text = [=[Grull Hawkwind é filho do {link:chief-hawkwind}Chefe Hawkwind{/link} e caçador da {link:red-cloud-mesa}Chapada Nuvem Vermelha{/link}. Ele põe à prova os jovens que chegam à {link:camp-narache}Aldeia Narache{/link} antes que se apresentem a seu pai. Ensina que os {link:tauren}tauren{/link} caçam por necessidade e também por esporte, e que uma fera é abatida para alimentar e vestir a tribo, nunca como mero troféu.]=],
		},
		{
			title = "Importância",
			text = [=[Grull dá aos jovens sua primeira caçada, e com ela a primeira lição da vida {link:tauren}tauren{/link}: tirar da terra só o que a tribo precisa.]=],
		},
		{
			title = "Feitos",
			text = [=[• Envia os jovens para caçar moas das planícies em busca de carne e penas.
• Pede peles de puma da montanha para vestir as crianças e remendar as tendas.
• Envia caçadores contra os javalis de guerra da {link:brambleblade-ravine}Ravina da Lâmina Espinhenta{/link}.]=],
		},
	},
