	allegiance = "Tauren · tribo Bloodhoof · Horda",
	aliases = { "Baine" },
	sections = {
		{
			title = "Resumo",
			text = [=[Baine Bloodhoof é filho de {link:cairne-bloodhoof}Cairne Bloodhoof{/link} e chefe da {link:bloodhoof-village}Aldeia Casco Sangrento{/link}. Ele governa o coração de {link:mulgore}Mulgore{/link} enquanto seu pai governa do {link:thunder-bluff}Penhasco do Trovão{/link}. É paciente com os que querem compartilhar a terra, e severo com os que não querem. Já viu muitos dos conflitos que ferem o mundo, e espera que os jovens de sua tribo vejam menos.]=],
		},
		{
			title = "Importância",
			text = [=[Baine é a próxima geração dos Bloodhoof. Os jovens que passam por sua aldeia aprendem com ele o que significa defender a terra natal {link:tauren}tauren{/link}.]=],
		},
		{
			title = "Feitos",
			text = [=[• Dá continuidade aos {link:rites-of-the-earthmother}Ritos da Mãe Terra{/link}, e envia os jovens ao líder espiritual {link:zarlman-two-moons}Zarlman Two-Moons{/link} para o Rito da Visão.
• Ordenou que os {link:palemane-gnolls}gnolls Jubalba{/link} fossem rechaçados quando recusaram toda tentativa de paz.
• Ordenou que as ferramentas dos escavadores anões fossem destruídas.
• Às vezes recorre aos {link:longwalkers}Andarilhos{/link}, os batedores de seu pai, em busca de ajuda.
• Liderou a defesa contra um bando de saqueadores Galath nestes dias.]=],
		},
	},
	chapters = {
		{
			title = "Compartilhando a Terra",
			hint = "Conheça o julgamento do chefe sobre os gnolls de Mulgore.",
			text = [=[Os {link:palemane-gnolls}gnolls Jubalba{/link} vieram a {link:mulgore}Mulgore{/link} e mataram sua vida selvagem sem freio. Os {link:tauren}tauren{/link} tentaram repetidas vezes alcançá-los com palavras. Baine enfim concluiu que as palavras não eram mais a resposta. Ele quis mostrar aos jovens como até uma pequena ameaça pode se tornar terrível se for deixada sem controle.]=],
		},
		{
			title = "Nosso Antigo Inimigo",
			hint = "Lide com os centauros que cruzaram para dentro de Mulgore.",
			text = [=[Quando o relatório da {link:longwalkers}Andarilha{/link} Malah, morta, chegou até ele, Baine o leu em silêncio. Então declarou que os {link:tauren}tauren{/link} não cederiam aos centauros uma única folha de capim. Enviou guerreiros para atacar o acampamento Galath antes que seus cavaleiros pudessem chegar à sua aldeia, e pediu que a cabeça do líder deles fosse trazida como aviso aos outros.]=],
		},
		{
			title = "O Filho Cativo",
			hint = "Conheça os dias em que Baine foi levado pelos centauros.",
			text = [=[Nos meses depois que os {link:tauren}tauren{/link} se estabeleceram em {link:mulgore}Mulgore{/link}, centauros capturaram Baine. Seu pai caiu num desespero tão fundo que não quis mais liderar. Foram o {link:orcs}orc{/link} {link:rexxar}Rexxar{/link} e o tauren Bovan Windtotem que encontraram Baine e o trouxeram para casa. Quando Baine hoje envia os jovens a seu pai, fala com orgulho do dia em que {link:cairne-bloodhoof}Cairne{/link} cavalgou com {link:thrall}Thrall{/link} para retomar estas planícies.]=],
		},
	},
	mentions = {
		{
			text = [=[{link:rites-of-the-earthmother}Ritos da Mãe Terra{/link}, trazidos do {link:chief-hawkwind}Chefe Hawkwind{/link}]=],
		},
		{ text = "Rito da Visão" },
		{ text = "Escavação Anã" },
		{ text = "Nosso Antigo Inimigo, o relatório que ele recebeu" },
		{ text = "O Chefe Supremo" },
	},
	bonds = {
		{ id = "cairne-bloodhoof", name = "Cairne Bloodhoof", note = "seu pai" },
		{ id = "chief-hawkwind", name = "Chefe Hawkwind", note = "envia-lhe os jovens" },
		{ id = "zarlman-two-moons", name = "Zarlman Two-Moons", note = "líder espiritual de sua aldeia" },
		{ id = "brave-wildrunner", name = "Bravo Wildrunner", note = "um bravo de sua aldeia" },
		{ id = "herak-the-pillager", name = "Herak, o Saqueador", note = "inimigo" },
	},
})

