Translate("ptBR", "muln-earthfury", {
	title = "Muln Earthfury",
	subtitle = "Ancião da Harmonia Telúrica",
	found = "Camp Gev'rek, no Skywatcher Plateau",
	hint = "Procure o velho xamã que acolhe os Skyborne em Mulgore.",
	allegiance = "Harmonia Telúrica · Tauren",
	aliases = { "Muln" },
	sections = {
		{
			title = "Resumo",
			text = [=[Muln Earthfury é um xamã {link:tauren}tauren{/link} e um líder da {link:earthen-ring}Harmonia Telúrica{/link}, o conselho que mantém o equilíbrio dos {link:elements}Elementos{/link}. Nestes dias, seu dever para com os espíritos o levou além do próprio mundo, a {link:skywall}Skywall{/link}, o reino do ar. Lá ele atendeu ao chamado dos {link:windshapers}Windshapers{/link}, e quando voltou trouxe-os consigo.]=],
		},
		{
			title = "Importância",
			text = [=[Muln é a ponte entre os {link:skyborne}Skyborne{/link} e {link:azeroth}Azeroth{/link}. Por meio dele, os {link:windshapers}Windshapers{/link} encontraram a {link:earthen-ring}Harmonia Telúrica{/link}, e por meio da Ring encontraram a {link:horde}Horda{/link}. Os elfos que descem a {link:mulgore}Mulgore{/link} são seus hóspedes, e conhecem o mundo primeiro por seu acampamento e seus conselhos.]=],
		},
		{
			title = "Feitos",
			text = [=[• Atendeu à súplica da líder dos {link:windshapers}Windshapers{/link}, {link:ayessa-dawnsinger}Ayessa Dawnsinger{/link}, cujo lar estava sucumbindo.
• Foi com xamãs da {link:earthen-ring}Harmonia Telúrica{/link} a {link:zephras-isle}Zephras Isle{/link} para ajudar os {link:skyborne}Skyborne{/link}.
• Enfrentou um dos grandes senhores do vento e lhe disse que a Ring não tinha nenhuma desavença com ele.
• Advertiu os Windshapers sobre os senhores elementais, e sobre as boas razões para temer {link:al-akir}Al'Akir{/link}.
• Abriu uma rota de navios celestes entre Zephras Isle e {link:mulgore}Mulgore{/link}.
• Mantém o acampamento no {link:camp-gev-rek}Skywatcher Plateau{/link} onde os recém-chegados desembarcam.]=],
		},
		{
			title = "Sem Registro",
			text = [=[Pouco se escreveu sobre a vida de Muln antes destes dias. As crônicas desta era não registram quando ele passou a liderar a Ring, ou como {link:ayessa-dawnsinger}Ayessa{/link} o alcançou pela primeira vez através dos planos.]=],
		},
	},
	chapters = {
		{
			title = "Ajuda de Baixo",
			hint = [=[Fique ao lado dos Windshapers em sua hora mais sombria em Zephras Isle.]=],
			text = [=[Os {link:windshapers}Windshapers{/link} haviam pedido ajuda, e ela demorou a chegar. Quando Muln e os xamãs da {link:earthen-ring}Harmonia Telúrica{/link} enfim chegaram, a batalha contra o culto da Alta Sacerdotisa {link:high-priestess-lorthuna}Lorthuna{/link} já estava em curso. Ele pediu perdão a {link:ayessa-dawnsinger}Ayessa{/link} por chegar tarde. Quando o Senhor do Vento Leste caiu sobre eles, Muln falou pela Ring: não tinham desavença com ele, e pediam apenas que os deixasse em paz. Terminada a batalha, voltou imediatamente a {link:azeroth}Azeroth{/link}.]=],
		},
		{
			title = "O Aviso",
			hint = [=[Descubra o que a Harmonia Telúrica contou aos Windshapers sobre o Senhor dos Ventos.]=],
			text = [=[Muln contou a {link:ayessa-dawnsinger}Ayessa{/link} muito sobre os senhores elementais. O que ele lhe contou deixou-a com medo. As proteções que haviam escondido {link:zephras-isle}Zephras Isle{/link} tinham desaparecido, e nada mais se interpunha entre a ilha e {link:al-akir}Al'Akir{/link} em seu próprio domínio. O Alto Ancião dos {link:skyborne}Skyborne{/link} via mais longe: para um senhor elemental, anos ou mesmo décadas poderiam passar antes que ele voltasse os olhos para eles.]=],
		},
		{
			title = "A Rota dos Navios Celestes",
			hint = "Embarque de Zephras Isle para a terra da Harmonia Telúrica.",
			text = [=[Muln trabalhou duro para tornar a travessia segura. Viagens de teste navegaram entre a ilha e {link:mulgore}Mulgore{/link}, onde a {link:earthen-ring}Harmonia Telúrica{/link} tem seu lar, até que os navios celestes passassem a correr com regularidade e os primeiros {link:skyborne}Skyborne{/link} já esperassem do outro lado.]=],
		},
	},
	mentions = {
		{
			text = [=[A {link:earthen-ring}Harmonia Telúrica{/link}, seu acampamento em {link:mulgore}Mulgore{/link}]=],
		},
		{ text = "Filha da Natureza" },
		{ text = "Explorando a {link:horde}Horda{/link}" },
	},
	bonds = {
		{ id = "alaana-stormwalker", name = "Alaana Stormwalker", note = "recebe os Windshapers em seu acampamento" },
		{ id = "cairne-bloodhoof", name = "Cairne Bloodhoof", note = "Chefe Supremo de seu povo" },
		{ id = "thrall", name = "Thrall", note = "Chefe Guerreiro da Horda e xamã" },
		{ id = "hamuul-runetotem", name = "Hamuul Runetotem", note = "do Círculo Cenariano, que acolhe seus hóspedes" },
	},
})

