	},
})

Translate("ptBR", "herak-the-pillager", {
	title = "Herak, o Saqueador",
	subtitle = "Saqueador dos Galath",
	found = "Um acampamento centauro na fronteira leste de Mulgore",
	hint = [=[Enfrente o saqueador centauro que cruzou para dentro de Mulgore.]=],
	allegiance = "Centauros Galath",
	aliases = { "Herak" },
	sections = {
		{
			title = "Resumo",
			text = [=[Herak, o Saqueador, lidera um pequeno bando de saqueadores {link:centaurs}centauros{/link} Galath que se infiltrou em {link:mulgore}Mulgore{/link} pelo leste. Seus cavaleiros mataram a {link:longwalkers}Andarilha{/link} Malah Longwind com flechas nas costas e ergueram um acampamento dentro das fronteiras {link:tauren}tauren{/link}. Herak reivindica as planícies para os Galath e jura vingança contra os tauren. Seus cavaleiros pretendiam descansar antes de atacar a {link:bloodhoof-village}Aldeia Casco Sangrento{/link}, e mandar buscar mais nos {link:the-barrens}Sertões{/link}.]=],
		},
		{
			title = "Importância",
			text = [=[Herak é um sinal de que os centauros não esqueceram {link:mulgore}Mulgore{/link}, e de que a vitória de {link:cairne-bloodhoof}Cairne{/link} ainda precisa ser defendida.]=],
		},
		{
			title = "Feitos",
			text = [=[• Seus cavaleiros mataram a {link:longwalkers}Andarilha{/link} Malah.
• Liderou um bando de saqueadores para dentro de {link:mulgore}Mulgore{/link}.]=],
		},
	},
	mentions = {
		{ text = "Expulse-os" },
	},
	bonds = {
		{ id = "baine-bloodhoof", name = "Baine Bloodhoof", note = "quer a cabeça dele" },
	},
})

Translate("ptBR", "bristleback-quilboar", {
	title = "Javatuscos Costagulha",
	aliases = { "javatuscos Costagulha", "Costagulhas", "Costagulha" },
	sections = {
		{
			title = "Resumo",
			text = [=[Os Costagulha são a tribo de {link:quilboar}javatuscos{/link} que vive em {link:mulgore}Mulgore{/link}. Estavam lá antes de os {link:tauren}tauren{/link} se estabelecerem nas planícies, e estão em guerra com eles desde então. De sua aldeia espinhosa na {link:brambleblade-ravine}Ravina da Lâmina Espinhenta{/link}, atacam {link:the-shimmering-flats}a Chapada{/link} Nuvem Vermelha, e seus saqueadores chegam ao norte até o cemitério do {link:red-rocks}Rochedo Vermelho{/link}.]=],
		},
		{
			title = "Modos de Guerra",
			text = [=[Os Costagulha lutam de emboscada. Seus guerreiros esperam à espreita pelos grupos de caça {link:tauren}tauren{/link} e se infiltram na {link:camp-narache}Aldeia Narache{/link} no escuro. Seus xamãs lutam ao lado deles. Treinam javalis de guerra, os grandes javalis da ravina, para serem maldosos, e os soltam nos campos de caça tauren. Seu chefe guerreiro traçou planos para um longo cerco à Aldeia Narache.]=],
		},
		{
			title = "Nestes Dias",
			text = [=[Os jovens {link:tauren}tauren{/link} de {link:camp-narache}Narache{/link} provam sua força contra os Costagulha, e os cintos dos saqueadores caídos são os primeiros troféus do Rito da Força. Invasores Costagulha andam devastando os túmulos do {link:red-rocks}Rochedo Vermelho{/link}. Seu chefe, {link:chief-sharptusk-thornmantle}Sharptusk Thornmantle{/link}, governa a ravina.]=],
		},
	},
})

Translate("ptBR", "palemane-gnolls", {
	title = "Gnolls Jubalba",
	aliases = { "gnolls Jubalba", "Jubalba" },
	sections = {
		{
			title = "Resumo",
			text = [=[Os Jubalba são uma tribo de {link:gnolls}gnolls{/link} que se instalou em {link:mulgore}Mulgore{/link}. Têm seu covil na caverna do {link:palemane-rock}Rochedo Jubalba{/link}, nas colinas do oeste, e mantêm acampamentos ao sul da {link:bloodhoof-village}Aldeia Casco Sangrento{/link}. São caçadores ilegais, esfoladores e curtidores, e matam a vida selvagem das planícies sem freio.]=],
		},
		{
			title = "Os Tauren e os Jubalba",
			text = [=[Os {link:tauren}tauren{/link} tentaram compartilhar a terra com eles. Repetidas vezes procuraram falar com os gnolls, e a cada vez foram recebidos com desrespeito. O Chefe {link:baine-bloodhoof}Baine Bloodhoof{/link} enfim julgou que as palavras não eram mais a resposta. Mesmo assim, o Chefe Supremo fez mais uma tentativa nestes dias, e enviou a eles seu {link:longwalkers}Andarilho{/link} {link:perith-stormhoof}Perith Stormhoof{/link}. Os gnolls o capturaram e o mantiveram em sua caverna.]=],
		},
		{
			title = "Seus Covis",
			text = [=[Os curtidores e esfoladores da tribo trabalham os couros de suas presas em volta do {link:palemane-rock}Rochedo Jubalba{/link}, enquanto os caçadores ilegais percorrem as colinas do oeste. Entre os acampamentos ao sul da {link:bloodhoof-village}Aldeia Casco Sangrento{/link} espreita um {link:gnolls}gnoll{/link} chamado Snagglespear.]=],
		},
	},
})

Translate("ptBR", "windfury-harpies", {
	title = "Harpias Ventofúria",
	aliases = { "harpias Ventofúria", "Ventofúria" },
	sections = {
		{
			title = "Resumo",
			text = [=[As Ventofúria são as {link:harpies}harpias{/link} de {link:mulgore}Mulgore{/link}. Seus bandos fazem ninho nas bordas das montanhas do sudeste, longe das estradas, e sobretudo na {link:windfury-ridge}Serra Ventofúria{/link}, no extremo norte. Os {link:tauren}tauren{/link} as contam entre os inimigos naturais de sua terra.]=],
		},
		{
			title = "Natureza",
			text = [=[Os bandos Ventofúria são governados por matriarcas, e suas bruxas e feiticeiras comandam o vento. Caçam o que quer que ande abaixo de seus poleiros. Sua plumagem é apreciada pelos {link:tauren}tauren{/link}: as penas azuis e bronze dos bandos do norte são usadas nos cocares que os jovens tauren vestem quando se apresentam ao Chefe Supremo.]=],
		},
		{
			title = "Nestes Dias",
			text = [=[{link:ruul-eagletalon}Ruul Eagletalon{/link}, da {link:bloodhoof-village}Aldeia Casco Sangrento{/link}, envia jovens guerreiros contra os bandos do sudeste como prova de força. Os bandos do norte são mais fortes, e suas feiticeiras e matriarcas governam as alturas da {link:windfury-ridge}Serra Ventofúria{/link}. Uma {link:harpies}harpia{/link} chamada Irmã Hatelash foi vista entre os rochedos do noroeste, não longe do platô onde a {link:earthen-ring}Harmonia Telúrica{/link} montou seu acampamento.]=],
		},
	},
})

Translate("ptBR", "longwalkers", {
	title = "Andarilhos",
	aliases = { "Andarilho", "Andarilha" },
	sections = {
		{
			title = "Resumo",
			text = [=[Os Andarilhos são os batedores de maior confiança dos {link:tauren}tauren{/link}. Respondem somente ao Chefe Supremo {link:cairne-bloodhoof}Cairne Bloodhoof{/link}, e levam suas missões mais secretas. Um Andarilho pode ser reconhecido por uma faixa na cabeça e um cajado com penas. Até o chefe da {link:bloodhoof-village}Aldeia Casco Sangrento{/link}, o próprio filho de Cairne, pode apenas pedir sua ajuda.]=],
		},
		{
			title = "Seus Costumes",
			text = [=[O segredo é a primeira lei dos Andarilhos. Viajam sozinhos, não falam de suas missões, e quando um deles é salvo do perigo segue sozinho em vez de contar a alguém para onde vai. Quando um Andarilho não volta de uma vigia, os bravos da aldeia mais próxima precisam ir descobrir por quê.]=],
		},
		{
			title = "Nestes Dias",
			text = [=[Dois Andarilhos correram perigo em {link:mulgore}Mulgore{/link}. {link:perith-stormhoof}Perith Stormhoof{/link}, a quem {link:cairne-bloodhoof}Cairne{/link} chama de seu batedor de maior confiança, foi enviado para negociar com os {link:palemane-gnolls}gnolls Jubalba{/link} e foi feito prisioneiro. Malah Longwind foi enviada para vigiar a fronteira leste e foi morta por centauros Galath, com o relatório ainda na mão.]=],
		},
	},
})

Translate("ptBR", "rites-of-the-earthmother", {
	title = "Ritos da Mãe Terra",
	aliases = { "Ritos da Mãe-Terra" },
	sections = {
		{
			title = "Resumo",
			text = [=[Os Ritos da Mãe Terra são as provas pelas quais um jovem {link:tauren}tauren{/link} conquista o respeito dos anciãos do {link:thunder-bluff}Penhasco do Trovão{/link}. São três: o Rito da Força, o Rito da Visão e o Rito da Sabedoria. Juntos, levam do primeiro acampamento na {link:red-cloud-mesa}Chapada Nuvem Vermelha{/link} à cabana do Chefe Supremo.]=],
		},
		{
			title = "Os Três Ritos",
			text = [=[• {b}O Rito da Força.{/b} O {link:chief-hawkwind}Chefe Hawkwind{/link} e o vidente {link:seer-graytongue}Graytongue{/link} enviam os jovens contra os saqueadores {link:bristleback-quilboar}Costagulha{/link} da {link:brambleblade-ravine}Ravina da Lâmina Espinhenta{/link}, para trazer de volta seus cintos como prova de bravura.
• {b}O Rito da Visão.{/b} Na {link:bloodhoof-village}Aldeia Casco Sangrento{/link}, {link:zarlman-two-moons}Zarlman Two-Moons{/link} prepara a Água dos Videntes com pedras de poço e bolotas-âmbar. Bebida diante da fogueira da tribo, ela invoca uma visão das planícies que conduz quem a bebe ao vidente {link:seer-wiserunner}Wiserunner{/link}.
• {b}O Rito da Sabedoria.{/b} No {link:red-rocks}Rochedo Vermelho{/link}, os espíritos ancestrais dão sua bênção aos que beberam a Água dos Videntes.]=],
		},
		{
			title = "O Fim da Jornada",
			text = [=[Os que passam pelos ritos são honrados no {link:thunder-bluff}Penhasco do Trovão{/link}. Seu último passo é subir à chapada mais alta e se apresentar a {link:cairne-bloodhoof}Cairne Bloodhoof{/link}. Mesmo então a prova não terminou. Para manter o lugar que conquistaram, o Chefe Supremo os envia para rastrear e abater Arra'chea, um poderoso kodo das planícies.]=],
		},
	},
})
